/**
 * Product data-access layer.
 *
 * All Supabase queries for the `products` table live here.
 * `product_code` and `barcode` are auto-generated by the DB trigger
 * `products_set_product_code` — the application never generates them.
 */

import { createClient } from "@/lib/supabase/client";
import type { Product, NewProduct } from "@/types/database";

// ─── Extended types ──────────────────────────────────────────────────────────

/** Product row joined with its parent category name. */
export interface ProductWithCategory extends Product {
  categories: { name: string } | null;
}

// ─── Query options ───────────────────────────────────────────────────────────

export interface GetProductsOptions {
  search?: string;
  categoryId?: string;
  /** 1-based page number (default: 1) */
  page?: number;
  /** Items per page (default: 20) */
  limit?: number;
}

export interface GetProductsResult {
  data: ProductWithCategory[];
  /** Total matching row count (for pagination). */
  count: number;
}

// ─── Queries ────────────────────────────────────────────────────────────────

/**
 * Paginated product list with optional search and category filter.
 * Joins the parent category name for display.
 */
export async function getProducts(
  opts: GetProductsOptions = {}
): Promise<GetProductsResult> {
  const supabase = createClient();
  const { search, categoryId, page = 1, limit = 20 } = opts;

  // Build query — cast to any to work around strict Supabase inference on joins
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  let query: any = supabase
    .from("products")
    .select("*, categories(name)", { count: "exact" });

  if (search && search.trim()) {
    const term = search.trim();
    query = query.or(
      `name.ilike.%${term}%,product_code.ilike.%${term}%,barcode.ilike.%${term}%`
    );
  }

  if (categoryId) {
    query = query.eq("category_id", categoryId);
  }

  const from = (page - 1) * limit;
  const to = from + limit - 1;

  const { data, error, count } = await query
    .order("created_at", { ascending: false })
    .range(from, to) as {
      data: ProductWithCategory[] | null;
      error: { message: string } | null;
      count: number | null;
    };

  if (error) throw new Error(error.message);

  return {
    data: data ?? [],
    count: count ?? 0,
  };
}

/**
 * Fetch a single product by primary key, joined with category name.
 * Returns null if not found.
 */
export async function getProductById(
  id: string
): Promise<ProductWithCategory | null> {
  const supabase = createClient();

  const { data, error } = (await supabase
    .from("products")
    .select("*, categories(name)")
    .eq("id", id)
    .maybeSingle()) as unknown as {
      data: ProductWithCategory | null;
      error: { message: string } | null;
    };

  if (error) throw new Error(error.message);
  return data;
}

// ─── Mutation input types ───────────────────────────────────────────────────

export interface CreateProductInput {
  name: string;
  category_id: string;
  selling_price: number;
  stock: number;
  image_url?: string | null;
  /** Controls public catalog visibility. Defaults to false if omitted. */
  is_published?: boolean;
  /** Marketing description shown on public product detail page. */
  description?: string | null;
  /** Technical specifications shown on public product detail page. */
  specifications?: string | null;
}

export interface UpdateProductInput {
  name?: string;
  category_id?: string;
  selling_price?: number;
  stock?: number;
  image_url?: string | null;
  /** Controls public catalog visibility. */
  is_published?: boolean;
  /** Marketing description shown on public product detail page. */
  description?: string | null;
  /** Technical specifications shown on public product detail page. */
  specifications?: string | null;
}

// ─── Mutations ──────────────────────────────────────────────────────────────

/**
 * Create a new product.
 *
 * `product_code` and `barcode` are intentionally omitted — the DB trigger
 * (`products_set_product_code`) generates and assigns them atomically, which
 * prevents race conditions when multiple admins create products simultaneously.
 *
 * Returns the created product row (with generated codes) joined with category.
 */
export async function createProduct(
  input: CreateProductInput
): Promise<ProductWithCategory> {
  const supabase = createClient();

  const payload: NewProduct = {
    name: input.name.trim(),
    category_id: input.category_id,
    selling_price: input.selling_price,
    stock: input.stock,
    image_url: input.image_url ?? null,
    is_published: input.is_published ?? false,
    description: input.description ?? null,
    specifications: input.specifications ?? null,
    // product_code and barcode deliberately omitted → generated by trigger
  };

  const { data, error } = (await supabase
    .from("products")
    .insert(payload as never)
    .select("*, categories(name)")
    .single()) as unknown as {
      data: ProductWithCategory;
      error: { message: string } | null;
    };

  if (error) throw new Error(error.message);
  return data;
}

/**
 * Update a product's mutable fields.
 * `product_code` and `id` are never updated.
 */
export async function updateProduct(
  id: string,
  input: UpdateProductInput
): Promise<ProductWithCategory> {
  const supabase = createClient();

  const updates: Record<string, unknown> = {};
  if (input.name !== undefined) updates.name = input.name.trim();
  if (input.category_id !== undefined) updates.category_id = input.category_id;
  if (input.selling_price !== undefined) updates.selling_price = input.selling_price;
  if (input.stock !== undefined) updates.stock = input.stock;
  if (input.image_url !== undefined) updates.image_url = input.image_url;
  if (input.is_published !== undefined) updates.is_published = input.is_published;
  if (input.description !== undefined) updates.description = input.description;
  if (input.specifications !== undefined) updates.specifications = input.specifications;

  const { data, error } = (await supabase
    .from("products")
    .update(updates as never)
    .eq("id", id)
    .select("*, categories(name)")
    .single()) as unknown as {
      data: ProductWithCategory;
      error: { message: string } | null;
    };

  if (error) throw new Error(error.message);
  return data;
}

/**
 * Delete a product by primary key.
 * The DB cascade deletes its transaction history automatically.
 */
export async function deleteProduct(id: string): Promise<void> {
  const supabase = createClient();
  const { error } = await supabase.from("products").delete().eq("id", id);
  if (error) throw new Error(error.message);
}

/**
 * Fetch the next product code from the DB RPC (display-only preview).
 * The authoritative code is always assigned by the DB trigger on INSERT.
 */
export async function getNextProductCode(): Promise<string> {
  const supabase = createClient();
  const { data, error } = await supabase.rpc("get_next_product_code");
  if (error) throw new Error(error.message);
  return (data as string) ?? "BRG000001";
}

// ─── Product Lookup (read-only) ──────────────────────────────────────────────

/**
 * Look up a product by its barcode (exact, case-insensitive).
 * Returns null when not found.
 */
export async function lookupProductByBarcode(
  barcode: string
): Promise<ProductWithCategory | null> {
  const supabase = createClient();
  const { data, error } = (await supabase
    .from("products")
    .select("*, categories(name)")
    .ilike("barcode", barcode.trim())
    .maybeSingle()) as unknown as {
      data: ProductWithCategory | null;
      error: { message: string } | null;
    };
  if (error) throw new Error(error.message);
  return data;
}

/**
 * Look up a product by its product code (exact, case-insensitive).
 * Returns null when not found.
 */
export async function lookupProductByCode(
  code: string
): Promise<ProductWithCategory | null> {
  const supabase = createClient();
  const { data, error } = (await supabase
    .from("products")
    .select("*, categories(name)")
    .ilike("product_code", code.trim())
    .maybeSingle()) as unknown as {
      data: ProductWithCategory | null;
      error: { message: string } | null;
    };
  if (error) throw new Error(error.message);
  return data;
}

/**
 * Universal product lookup — tries barcode first, then product_code.
 * Returns the first match or null.
 * Used by the Product Lookup page for all search modes.
 */
export async function lookupProduct(
  query: string
): Promise<ProductWithCategory | null> {
  const trimmed = query.trim();
  if (!trimmed) return null;

  const byBarcode = await lookupProductByBarcode(trimmed);
  if (byBarcode) return byBarcode;

  const byCode = await lookupProductByCode(trimmed);
  return byCode;
}
